sys_script.script:
(function executeRule(current, previous) {

    try {
        var participantAssignmentSysId = current.getValue('participant_assignment');

        // No Participant Assignment attached → allow delete
        if (!participantAssignmentSysId)
            return;

        var participantGR = new GlideRecordSecure('x_ctans_incentnow_participant_assignment');

        if (!participantGR.get(participantAssignmentSysId)) {
            gs.addErrorMessage('The related Participant Assignment could not be found.');
            current.setAbortAction(true);
            return;
        }

        // Delete allowed only when Participant Assignment is Draft
        if (participantGR.getValue('status') != 'draft') {
            gs.addErrorMessage(
                'Quota Assignment cannot be deleted because the related Participant Assignment is not in Draft state.'
            );
            current.setAbortAction(true);
            return;
        }

    } catch (e) {
        gs.error(
            '[IncentIQ Quota Assignment] Delete validation failed. ' +
            'Quota Assignment=' + current.getUniqueValue() +
            ', Error=' + e.message
        );

        gs.addErrorMessage('Quota Assignment could not be deleted because delete validation failed.');
        current.setAbortAction(true);
    }

})(current, previous);
